template <class T> struct char_traits;          // primary: unknown types stay unsupported
template <> struct char_traits<char> {         // specialize for types you cannot edit
    using char_type = char;
    using int_type  = int;
    static constexpr int_type eof() { return EOF; }
};
template <class charT, class traits = char_traits<charT>>
class basic_streambuf {                        // the algorithm names only the trait
    using int_type = typename traits::int_type;
    int_type eof() { return traits::eof(); }
};

template <class T, class = void> struct has_value_type : std::false_type {};

template <class T>
struct has_value_type<T, std::void_t<typename T::value_type>> : std::true_type {};

template <class T>
constexpr bool has_value_type_v = has_value_type<T>::value;

template <class T, std::enable_if_t<has_value_type_v<T>, int> = 0>
void consume(const T& c) { typename T::value_type first = *c.begin(); }

template <class T>
concept Measurable = requires(const T& t) {
    { t.size() } -> std::convertible_to<std::size_t>;
    typename T::value_type;
};

template <Measurable T>                    // more constrained overload wins by subsumption
auto total(const T& t) {
    return std::accumulate(t.begin(), t.end(), typename T::value_type{});
}

